package uk.ac.ravensbourne.casevault.web;
import jakarta.validation.Valid; import jakarta.validation.constraints.*; import org.springframework.security.core.annotation.AuthenticationPrincipal; import org.springframework.stereotype.Controller; import org.springframework.web.bind.annotation.*; import uk.ac.ravensbourne.casevault.security.*;
@Controller public class ChangePasswordController { private final PasswordChangeService passwords; public ChangePasswordController(PasswordChangeService p){passwords=p;} @GetMapping("/password/change") String form(){return "change-password";} @PostMapping("/password/change") String change(@AuthenticationPrincipal UserPrincipal p,@Valid @ModelAttribute ChangePasswordRequest request){passwords.change(p,request.currentPassword(),request.newPassword());return "redirect:/login?passwordChanged";} public record ChangePasswordRequest(@NotBlank String currentPassword,@NotBlank @Size(max=128) String newPassword){} }
